-- Leads generated by the public one-month trial request form. Only the
-- service role may read or mutate these rows; the public form writes through
-- a validated server route.

CREATE TABLE public.trial_requests (
  id UUID PRIMARY KEY DEFAULT extensions.uuid_generate_v4(),
  contact_name TEXT NOT NULL CHECK (char_length(contact_name) BETWEEN 3 AND 160),
  email TEXT NOT NULL,
  phone TEXT NOT NULL,
  board_role TEXT NOT NULL CHECK (board_role IN ('presidente', 'secretario', 'tesorero', 'dirigente', 'otro')),
  junta_name TEXT NOT NULL CHECK (char_length(junta_name) BETWEEN 3 AND 160),
  region TEXT NOT NULL,
  comuna TEXT NOT NULL,
  member_count INTEGER CHECK (member_count IS NULL OR member_count BETWEEN 1 AND 100000),
  requested_plan TEXT NOT NULL DEFAULT 'juntapp' CHECK (requested_plan IN ('juntapp', 'juntapp_web', 'web')),
  message TEXT,
  status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'contacted', 'converted', 'discarded')),
  source TEXT,
  utm_source TEXT,
  utm_medium TEXT,
  utm_campaign TEXT,
  utm_content TEXT,
  created_junta_id UUID REFERENCES public.juntas(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

CREATE INDEX idx_trial_requests_status_created
  ON public.trial_requests (status, created_at DESC);
CREATE INDEX idx_trial_requests_email
  ON public.trial_requests (lower(email));

ALTER TABLE public.trial_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.trial_requests FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.trial_requests TO service_role;

COMMENT ON TABLE public.trial_requests IS
  'Public requests for a personalized one-month JuntAPP trial, managed by Superadmin.';
